  /// Permission denied(13)
  static const int INM_ERROR_PERMISSION_DENIED = -13;

  /// Device or resource busy(16)
  static const int INM_ERROR_RESOURCE_BUSY = -16;

  /// Invalid function parameter(22)
  static const int INM_ERROR_INVALID_PARAMETER = -22;

  /// Connection timed out(110)
  static const int INM_ERROR_CONNECTION_TIME_OUT = -110;

  /// Now in progress(115)
  static const int INM_ERROR_NOW_IN_PROGRESS = -115;

  /// Not supported
